//	    {
//	      case CUPTI_CB_DOMAIN_RUNTIME_API:
//	      case CUPTI_CB_DOMAIN_DRIVER_API:
//	        if (cbInfo->callbackSite == CUPTI_API_EXIT) {
//	            // call the CUPTI detach API
